BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SELECT 'MONEY_DEV_PREFLIGHT_BEGIN'; SELECT json_build_object('database',current_database(),'readOnly',current_setting('transaction_read_only'),'history',(SELECT string_agg(version||'='||checksum,',' ORDER BY installed_rank) FROM public.flyway_schema_history WHERE version IS NOT NULL),'scriptsDigest',(SELECT md5(string_agg(script,'|' ORDER BY installed_rank)) FROM public.flyway_schema_history WHERE version IS NOT NULL),'failed',(SELECT count(*) FROM public.flyway_schema_history WHERE NOT success),'presetConflicts',(SELECT count(*) FROM (SELECT t.user_id,p->>'id' FROM public.money_work_templates t CROSS JOIN LATERAL jsonb_array_elements(t.data->'presets') p GROUP BY t.user_id,p->>'id' HAVING count(DISTINCT p)>1) q),'workplaceTable',to_regclass('public.money_workplaces')); SELECT json_build_object('table','money_coupang_work_records','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_coupang_work_records t; SELECT json_build_object('table','money_work_templates','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_work_templates t; SELECT json_build_object('table','money_work_earnings_weeks','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_work_earnings_weeks t; SELECT json_build_object('table','money_work_payments','count',count(*),'digest',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) FROM public.money_work_payments t; SELECT json_build_object('table','money_transactions','count',count(*),'digest',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) FROM public.money_transactions t; SELECT 'MONEY_DEV_PREFLIGHT_END'; ROLLBACK;

BEGIN READ ONLY; SELECT 'MONEY_MAPPING_BEGIN'; SELECT json_build_object('workplaces',(SELECT count(*) FROM public.money_workplaces),'mappedTemplates',(SELECT count(*) FROM public.money_work_templates WHERE workplace_id=md5('money-workplace:coupang:'||user_id)::uuid),'mappedRecords',(SELECT count(*) FROM public.money_coupang_work_records WHERE workplace_id=md5('money-workplace:coupang:'||user_id)::uuid),'mappedWeeks',(SELECT count(*) FROM public.money_work_earnings_weeks WHERE workplace_id=md5('money-workplace:coupang:'||user_id)::uuid),'ownerFks',(SELECT count(*) FROM pg_constraint WHERE conname IN ('money_template_workplace_fk','money_record_workplace_fk','money_week_workplace_fk') AND convalidated),'rls',(SELECT relrowsecurity FROM pg_class WHERE oid='public.money_workplaces'::regclass),'dateUnique',(SELECT count(*) FROM pg_constraint WHERE conname='money_coupang_work_records_user_id_work_date_key')); SELECT 'MONEY_MAPPING_END'; ROLLBACK;